}
// Les mêmes étapes, enchaînées d'un bloc (interface simulée, tests).
function traiterQuestionnaire(texte, { caisse, annee, id = null, lu = null }) {
  let e = demarrerTraitement(texte, { annee, id, lu });
  e = etapeControler(e);
  e = etapeCaisse(e, caisse);
