      "taux_retraite": 0.186,
      "pourcentages": {
        "5": { "pflegegeld": 1.0, "kombination": 0.85, "sachleistung": 0.7 },
        "4": { "pflegegeld": 0.7, "kombination": 0.595, "sachleistung": 0.49 },
        "3": { "pflegegeld": 0.43, "kombination": 0.3655, "sachleistung": 0.301 },
        "2": { "pflegegeld": 0.27, "kombination": 0.2295, "sachleistung": 0.189 }
