function lireIdentite(v) {
  const s = String(v).trim();
  if (s.includes(',')) {
    const [nom, ...reste] = s.split(',');
    return { nom: nom.trim(), prenom: reste.join(',').trim() };
  }
  const mots = s.split(/\s+/);
  return mots.length > 1 ? { nom: mots.pop(), prenom: mots.join(' ') } : { nom: s, prenom: '' };
