const dateDans = (v) => {
  const m = String(v).match(/\d{1,2}[./-]\d{1,2}[./-]\d{2,4}|\d{4}-\d{2}-\d{2}/);
  return m ? { iso: dateVersISO(m[0]), brut: m[0] } : null;
