    id: e.id,
    recu_le: e.lu.recu_le,
    aidant: `${donnees.aidant_prenom ?? ''} ${donnees.aidant_nom ?? ''}`.trim(),
    personne_soignee: `${donnees.personne_prenom ?? ''} ${donnees.personne_nom ?? ''}`.trim(),
    donnees,
