const CLES_IA_TEXTE = ['aidant_nom', 'aidant_prenom', 'aidant_naissance', 'numero_assurance', 'nationalite', 'adresse', 'personne_nom', 'personne_prenom', 'personne_naissance', 'ref_caisse', 'prestation', 'debut_soins', 'fin_soins'];
